    INSERT INTO ops.Incident (ShipmentId, MerchantId, CarrierId, Title, Description, Severity, IsResolved, CreatedAt, ResolvedAt)
    VALUES
    (@s1,  @acme, @fastex,   N'Повреждение упаковки в сортировочном центре',        N'В московский сортировочный центр Северный поступила посылка с повреждённой упаковкой. Коробка смята, содержимое цело. Оператор приложил фотографии. Посылка переупакована и отправлена дальше.', 2, 1, '2026-09-02T05:00:00', '2026-09-02T09:30:00'),
    (NULL, @acme, @fastex,   N'Посылка потеряна в пути',          N'Посылка покинула московский сортировочный центр, но не поступила в пункт назначения. Перевозчик начал розыск. Клиент запросил возврат денег.', 4, 0, '2026-09-03T10:00:00', NULL),
    (NULL, @acme, @cityrun,  N'Неудачная попытка доставки',         N'При первой попытке курьер не застал получателя. Повторная доставка назначена на следующий день с 10:00 до 14:00. Получатель уведомлён по СМС.', 1, 1, '2026-09-02T15:00:00', '2026-09-03T12:00:00'),
    (NULL, @kiddo, @nordpost, N'Задержка на сортировке',             N'Посылка задержалась в сортировочном центре Санкт-Петербурга на три дня из-за отсутствия накладной. Магазин передал документы, отправление выпущено.', 3, 1, '2026-09-06T08:00:00', '2026-09-09T16:00:00'),
    (NULL, @kiddo, @nordpost, N'Неверный адрес на этикетке',         N'На этикетке указано устаревшее название улицы. Курьер не нашёл адрес. Адрес исправлен через API, этикетка перепечатана в пункте выдачи.', 2, 1, '2026-09-07T11:00:00', '2026-09-07T15:00:00'),
    (NULL, @nordic, @fastex,  N'Повреждён хрупкий товар',            N'Получатель сообщил о повреждении велосипедной детали, несмотря на отметку Хрупкое. Упаковка повреждена при доставке. Перевозчику направлена претензия.', 3, 0, '2026-09-08T09:00:00', NULL),
    (NULL, @acme, @cityrun,  N'Доставлено другому получателю',    N'Посылку без согласования передали соседу. Получатель отправление не получил. На следующий день курьер забрал посылку и передал адресату.', 3, 1, '2026-09-08T14:00:00', '2026-09-09T13:00:00'),
    (NULL, @acme, @fastex,   N'Отсутствует сканирование на сортировке',                N'В отслеживании отсутствует сканирование на сортировке за 48 часов, хотя посылка доставлена вовремя. Ошибка качества данных перевозчика, клиент не пострадал.', 1, 1, '2026-09-09T10:00:00', '2026-09-09T10:30:00'),
    (NULL, @kiddo, @cityrun, N'Склад не принял возврат',     N'Склад магазина не принял возврат без номера разрешения. Посылка возвращена в пункт выдачи и ожидает инструкций.', 2, 0, '2026-09-10T12:00:00', NULL),
    (NULL, @nordic, @nordpost, N'Повреждение при перевозке',        N'Коробка смята при перевозке между Казанью и Санкт-Петербургом. Содержимое повреждено. Перевозчик признал ответственность, компенсация согласовывается.', 3, 0, '2026-09-10T16:00:00', NULL),
    (NULL, @acme, @fastex,   N'Доставка задержана из-за погоды',     N'Из-за непогоды региональный сортировочный центр не работал сутки. Доставка задержалась на 24 часа. Нарушение SLA отмечено для 120 отправлений.', 2, 1, '2026-09-11T07:00:00', '2026-09-12T18:00:00'),
    (NULL, @kiddo, @nordpost, N'Повторные события отслеживания',      N'Перевозчик трижды передал одинаковые события с разными идентификаторами. Дубли удалены вручную, перевозчик уведомлён об ошибке идемпотентности.', 1, 1, '2026-09-11T13:00:00', '2026-09-11T14:00:00'),
    (NULL, @acme, @cityrun,  N'Получатель отказался от доставки',      N'Получатель отказался от посылки из-за неверного товара. Отправление возвращено магазину. Магазин подтвердил ошибку комплектации.', 2, 1, '2026-09-12T11:00:00', '2026-09-13T09:00:00'),
    (NULL, @nordic, @fastex,  N'Доплата за негабаритное отправление',     N'Перевозчик начислил не предусмотренную тарифом доплату за негабарит. Магазин направил возражение. Счёт приостановлен до согласования.', 1, 0, '2026-09-12T15:00:00', NULL),
    (NULL, @acme, @fastex,   N'Посылка оставлена без присмотра',  N'Курьер оставил посылку у подъезда без подписи. Позже получатель её нашёл. Жалоба зарегистрирована, с курьером проведён разбор.', 2, 1, '2026-09-13T10:00:00', '2026-09-13T17:00:00'),
    (NULL, @kiddo, @cityrun, N'Этикетка не читается',                N'Штрихкод на этикетке размыт, сканер пункта выдачи его не прочитал. Ручная обработка задержала доставку на сутки.', 1, 1, '2026-09-13T12:00:00', '2026-09-14T10:00:00'),
    (NULL, @nordic, @nordpost, N'Утеряно в сортировочном центре',        N'Последнее сканирование выполнено в сортировочном центре Санкт-Петербурга. Новых событий нет семь дней. Посылка признана утерянной, претензия подана.', 4, 0, '2026-09-14T09:00:00', NULL),
    (NULL, @acme, @cityrun,  N'Не указан код домофона',             N'Курьер не попал в подъезд: в инструкции не указан код домофона. Получатель сообщил код, доставка перенесена.', 1, 1, '2026-09-14T13:00:00', '2026-09-15T11:00:00'),
    (NULL, @kiddo, @nordpost, N'Упаковка вскрыта при получении',    N'Посылка поступила со вскрытой коробкой и разрезанным скотчем. По словам получателя, вложение полное. Возможно, на сортировке проводился досмотр без отметки.', 2, 1, '2026-09-15T08:00:00', '2026-09-15T12:00:00'),
    (NULL, @nordic, @fastex,  N'Неверный вес в счёте',            N'В счёте перевозчика указан вес 12 кг, при отправке заявлено 3,2 кг. Запрошен акт повторного взвешивания. Ожидается исправление счёта.', 1, 0, '2026-09-15T14:00:00', NULL);
